import React, { useEffect, useState } from "react";
import { toast } from "react-toastify";

import {
  FiHeart,
  FiRefreshCw,
  FiSave,
} from "react-icons/fi";

import api, {
  getApiErrorMessage,
} from "../../services/api";

import { useLanguage } from "../../contexts/LanguageContext";



const initialForm = {
  // English
  hero_title_en: "",
  hero_description_en: "",
  impact_title_en: "",
  impact_description_en: "",
  support_title_en: "",
  support_description_en: "",
  support_options_en: "",
  cta_title_en: "",
  cta_description_en: "",

  // Khmer
  hero_title_km: "",
  hero_description_km: "",
  impact_title_km: "",
  impact_description_km: "",
  support_title_km: "",
  support_description_km: "",
  support_options_km: "",
  cta_title_km: "",
  cta_description_km: "",

  is_active: true,
};


const AdminCharity = () => {
  const { t, language } = useLanguage();

  const isKhmer =
    language === "km" ||
    language === "kh";


  const [form, setForm] =
    useState(initialForm);

  const [loading, setLoading] =
    useState(true);

  const [saving, setSaving] =
    useState(false);



  const tr = (
    key,
    english,
    khmer
  ) => {
    const value =
      typeof t === "function"
        ? t(key)
        : "";

    if (
      value &&
      value !== key &&
      !String(value).includes("undefined")
    ) {
      return value;
    }

    return isKhmer
      ? khmer
      : english;
  };




  const getErrorMessage = (
    error,
    fallback
  ) => {
    if (
      typeof getApiErrorMessage === "function"
    ) {
      return getApiErrorMessage(
        error,
        fallback
      );
    }

    const detail =
      error?.response?.data?.detail;

    if (typeof detail === "string") {
      return detail;
    }

    if (Array.isArray(detail)) {
      return detail
        .map((item) => item?.msg || item)
        .filter(Boolean)
        .join(", ");
    }

    return (
      error?.response?.data?.message ||
      error?.message ||
      fallback
    );
  };


  const fetchContent = async () => {
    try {
      setLoading(true);

      const response = await api.get(
        "/api/charity/"
      );

      setForm({
        ...initialForm,
        ...(response.data || {}),
      });
    } catch (error) {
      console.error(
        "Fetch charity content error:",
        error
      );

      toast.error(
        getErrorMessage(
          error,
          tr(
            "charity.loadFailed",
            "Failed to load charity content.",
            "មិនអាចទាញយកព័ត៌មានសប្បុរសធម៌បានទេ។"
          )
        )
      );
    } finally {
      setLoading(false);
    }
  };


  useEffect(() => {
    fetchContent();

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);


  const handleChange = (
    field,
    value
  ) => {
    setForm((current) => ({
      ...current,
      [field]: value,
    }));
  };






  const handleSubmit = async (
    event
  ) => {
    event.preventDefault();


    try {
      setSaving(true);

      const payload = {
        ...form,
        is_active: Boolean(form.is_active),
      };

      delete payload.id;
      delete payload.updated_at;

      const response = await api.put(
        "/api/charity/",
        payload
      );

      setForm({
        ...initialForm,
        ...(response.data || {}),
      });

      toast.success(
        tr(
          "charity.savedSuccess",
          "Charity content saved successfully.",
          "បានរក្សាទុកព័ត៌មានសប្បុរសធម៌ដោយជោគជ័យ។"
        )
      );
    } catch (error) {
      console.error(
        "Save charity content error:",
        error
      );

      toast.error(
        getErrorMessage(
          error,
          tr(
            "charity.saveFailed",
            "Failed to save charity content.",
            "មិនអាចរក្សាទុកព័ត៌មានសប្បុរសធម៌បានទេ។"
          )
        )
      );
    } finally {
      setSaving(false);
    }
  };


  const renderInput = (
    label,
    field,
    placeholder,
    multiline = false
  ) => (
    <label className="block">
      <span className="mb-2 block text-[12px] font-semibold text-gray-700">
        {label}
      </span>

      {multiline ? (
        <textarea
          value={form[field] || ""}
          onChange={(event) =>
            handleChange(
              field,
              event.target.value
            )
          }
          placeholder={placeholder}
          rows={
            field.includes("options")
              ? 5
              : 4
          }
          className="w-full resize-y rounded-lg border border-gray-200 px-4 py-3 text-[13px] text-gray-800 outline-none transition focus:border-blue-700 focus:ring-2 focus:ring-blue-100"
        />
      ) : (
        <input
          type="text"
          value={form[field] || ""}
          onChange={(event) =>
            handleChange(
              field,
              event.target.value
            )
          }
          placeholder={placeholder}
          className="h-11 w-full rounded-lg border border-gray-200 px-4 text-[13px] text-gray-800 outline-none transition focus:border-blue-700 focus:ring-2 focus:ring-blue-100"
        />
      )}
    </label>
  );




  if (loading) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <div className="h-10 w-10 animate-spin rounded-full border-4 border-gray-200 border-t-blue-900" />
      </div>
    );
  }


  return (
    <main className={`min-h-screen bg-slate-50 px-4 py-6 md:px-6 lg:px-8 ${isKhmer ? "font-khmer" : "font-english"}`}>
      <div className="mx-auto w-full max-w-[1450px]">
        {/* Header */}
        <div className="mb-6 overflow-hidden rounded-2xl bg-[#0B1849] text-white shadow-sm">
          <div className="relative px-5 py-6 md:px-8 md:py-8">
            <div className="pointer-events-none absolute -right-20 -top-24 h-64 w-64 rounded-full bg-red-600/10 blur-3xl" />
            <div className="pointer-events-none absolute -bottom-24 left-20 h-56 w-56 rounded-full bg-white/5 blur-3xl" />

            <div className="relative z-10 flex flex-col gap-5 md:flex-row md:items-center md:justify-between">
              <div>
                <div className="mb-2 flex items-center gap-2 text-red-400">
                  <span className="h-[2px] w-7 rounded-full bg-red-500" />
                  <span className="text-[11px] font-bold uppercase tracking-[0.18em]">
                    {tr("admin.panel", "SC Academy Admin", "ផ្ទាំងអ្នកគ្រប់គ្រង SC Academy")}
                  </span>
                </div>

                <h1 className="text-[28px] font-bold md:text-[36px]">
                  {tr(
                    "charity.title",
                    "Charity Management",
                    "គ្រប់គ្រងសកម្មភាពសប្បុរសធម៌"
                  )}
                </h1>

                <p className="mt-2 max-w-2xl text-[13px] leading-6 text-white/65">
                  {tr(
                    "charity.subtitle",
                    "Manage charity content shown on the public website.",
                    "គ្រប់គ្រងមាតិកាសប្បុរសធម៌ដែលបង្ហាញលើគេហទំព័រ។"
                  )}
                </p>
              </div>

              <button
                type="button"
                onClick={fetchContent}
                disabled={loading || saving}
                className="inline-flex h-10 items-center justify-center gap-2 rounded-lg border border-white/10 bg-white/10 px-4 text-[12px] font-semibold text-white backdrop-blur-sm transition hover:bg-white/20 disabled:cursor-not-allowed disabled:opacity-60"
              >
                <FiRefreshCw size={15} className={loading ? "animate-spin" : ""} />
                {tr("common.refresh", "Refresh", "ផ្ទុកឡើងវិញ")}
              </button>
            </div>
          </div>
        </div>

      <form
        onSubmit={handleSubmit}
        className="overflow-hidden rounded-xl border border-gray-200 bg-white shadow-sm"
      >
        {/* Form Header */}
        <div className="flex flex-col gap-4 border-b border-gray-100 px-5 py-4 sm:flex-row sm:items-center sm:justify-between">
          <div>
            <h2 className="text-[16px] font-bold text-blue-950">
              {tr(
                "charity.content",
                "Charity Content",
                "មាតិកាសប្បុរសធម៌"
              )}
            </h2>

            <p className="mt-1 text-[12px] text-gray-500">
              {tr(
                "charity.optionsHelp",
                "Enter support options one per line.",
                "សូមបញ្ចូលជម្រើសគាំទ្រមួយក្នុងមួយបន្ទាត់។"
              )}
            </p>
          </div>

          <label className="inline-flex cursor-pointer items-center gap-2 text-[12px] font-semibold text-gray-700">
            <input
              type="checkbox"
              checked={Boolean(
                form.is_active
              )}
              onChange={(event) =>
                handleChange(
                  "is_active",
                  event.target.checked
                )
              }
              className="h-4 w-4 accent-blue-900"
            />

            {tr(
              "common.active",
              "Active",
              "សកម្ម"
            )}
          </label>
        </div>

        {/* Single Language Content */}
        <div className="p-5">
          <section
            className={`space-y-4 rounded-xl border border-gray-200 p-4 ${
              isKhmer ? "font-khmer" : "font-english"
            }`}
          >
            <div className="border-b border-gray-100 pb-3">
              <h3 className="text-[13px] font-bold text-blue-900">
                {isKhmer ? "មាតិកាភាសាខ្មែរ" : "English Content"}
              </h3>
            </div>

            {renderInput(
              isKhmer ? "ចំណងជើង Hero" : "Hero Title",
              isKhmer ? "hero_title_km" : "hero_title_en",
              isKhmer
                ? "ផ្តល់ឱកាសឱ្យសិស្សកាន់តែច្រើនបានសិក្សា"
                : "Give Students More Chances to Learn"
            )}

            {renderInput(
              isKhmer ? "ការពិពណ៌នា Hero" : "Hero Description",
              isKhmer ? "hero_description_km" : "hero_description_en",
              isKhmer ? "សរសេរការណែនាំខ្លី..." : "Short introduction...",
              true
            )}

            {renderInput(
              isKhmer ? "ចំណងជើងផលប៉ះពាល់" : "Impact Title",
              isKhmer ? "impact_title_km" : "impact_title_en",
              isKhmer
                ? "គាំទ្រការអប់រំប្រកបដោយគោលបំណង"
                : "Support Education With Purpose"
            )}

            {renderInput(
              isKhmer ? "ការពិពណ៌នាផលប៉ះពាល់" : "Impact Description",
              isKhmer ? "impact_description_km" : "impact_description_en",
              isKhmer ? "ពិពណ៌នាអំពីផលប៉ះពាល់..." : "Describe the impact...",
              true
            )}

            {renderInput(
              isKhmer ? "ចំណងជើងការគាំទ្រ" : "Support Title",
              isKhmer ? "support_title_km" : "support_title_en",
              isKhmer
                ? "ការចូលរួមគ្រប់បែបយ៉ាងអាចបើកទ្វារឱកាស"
                : "Every Contribution Can Open a Door"
            )}

            {renderInput(
              isKhmer ? "ការពិពណ៌នាការគាំទ្រ" : "Support Description",
              isKhmer ? "support_description_km" : "support_description_en",
              isKhmer
                ? "ពិពណ៌នាពីរបៀបដែលមនុស្សអាចជួយ..."
                : "Describe how people can help...",
              true
            )}

            {renderInput(
              isKhmer ? "ជម្រើសការគាំទ្រ" : "Support Options",
              isKhmer ? "support_options_km" : "support_options_en",
              isKhmer ? "មួយជម្រើសក្នុងមួយបន្ទាត់" : "One option per line",
              true
            )}

            {renderInput(
              isKhmer ? "ចំណងជើង CTA" : "CTA Title",
              isKhmer ? "cta_title_km" : "cta_title_en",
              isKhmer
                ? "គាំទ្រសកម្មភាពសប្បុរសធម៌របស់ SC Academy"
                : "Support SC Academy Charity"
            )}

            {renderInput(
              isKhmer ? "ការពិពណ៌នា CTA" : "CTA Description",
              isKhmer ? "cta_description_km" : "cta_description_en",
              isKhmer
                ? "ទាក់ទងក្រុមការងារដើម្បីស្វែងយល់បន្ថែម..."
                : "Contact us to learn more...",
              true
            )}
          </section>
        </div>

        {/* Save */}
        <div className="flex justify-end border-t border-gray-100 px-5 py-4">
          <button
            type="submit"
            disabled={saving}
            className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-blue-900 px-6 text-[13px] font-bold text-white transition hover:bg-red-600 disabled:cursor-not-allowed disabled:opacity-60"
          >
            {saving ? (
              <>
                <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white" />

                {tr(
                  "common.saving",
                  "Saving...",
                  "កំពុងរក្សាទុក..."
                )}
              </>
            ) : (
              <>
                <FiSave size={16} />

                {tr(
                  "common.save",
                  "Save",
                  "រក្សាទុក"
                )}
              </>
            )}
          </button>
        </div>
      </form>
      </div>
    </main>
  );
};


export default AdminCharity;
